    "privacyPolicy": {
        "eyebrow": "\u6cd5\u5f8b",
        "title": "\u9690\u79c1\u653f\u7b56",
        "intro": "\u672c\u653f\u7b56\u8bf4\u660e Sea Requests \u5982\u4f55\u5904\u7406\u901a\u8fc7\u5e73\u53f0\u6536\u96c6\u7684\u4e2a\u4eba\u548c\u8fd0\u8425\u4fe1\u606f\u3002",
        "updated": "\u6700\u540e\u66f4\u65b0\uff1a2026 \u5e74 5 \u6708 13 \u65e5",
        "sections": [
            {
                "title": "\u6211\u4eec\u6536\u96c6\u7684\u4fe1\u606f",
                "paragraphs": [
                    "\u6ce8\u518c\u65f6\uff0c\u6211\u4eec\u4f1a\u6536\u96c6\u59d3\u540d\u3001\u7535\u5b50\u90ae\u4ef6\u5730\u5740\u3001\u516c\u53f8\u4fe1\u606f\u3001\u56fd\u5bb6\u3001\u7535\u8bdd\u53f7\u7801\u4ee5\u53ca\u53ef\u9009\u7684 WhatsApp \u53f7\u7801\u7b49\u8d26\u6237\u4fe1\u606f\u3002",
                    "\u6211\u4eec\u4e5f\u53ef\u80fd\u6536\u96c6\u4e0e\u8d26\u6237\u9a8c\u8bc1\u3001\u767b\u5f55\u6d3b\u52a8\u548c\u5e73\u53f0\u5185\u64cd\u4f5c\u76f8\u5173\u7684\u8fd0\u8425\u6570\u636e\u3002"
                ]
            },
            {
                "title": "\u6211\u4eec\u5982\u4f55\u4f7f\u7528\u4fe1\u606f",
                "paragraphs": [
                    "\u60a8\u7684\u4fe1\u606f\u7528\u4e8e\u521b\u5efa\u8d26\u6237\u3001\u9a8c\u8bc1\u8eab\u4efd\u3001\u5ba1\u6838\u4f9b\u5e94\u5546\u6ce8\u518c\u3001\u652f\u6301\u6c9f\u901a\u5e76\u5b89\u5168\u8fd0\u8425\u5e02\u573a\u3002",
                    "\u6211\u4eec\u53ef\u80fd\u4f1a\u4f7f\u7528\u8d26\u6237\u6570\u636e\u8054\u7cfb\u7528\u6237\uff0c\u5904\u7406\u9a8c\u8bc1\u3001\u6279\u51c6\u3001\u8bbf\u95ee\u95ee\u9898\u6216\u91cd\u8981\u5e73\u53f0\u66f4\u65b0\u3002"
                ]
            },
            {
                "title": "\u6570\u636e\u5171\u4eab",
                "paragraphs": [
                    "\u5f53\u4f9b\u5e94\u5546\u8d26\u6237\u83b7\u5f97\u6279\u51c6\u5e76\u53d1\u5e03\u540e\uff0c\u516c\u5f00\u4f9b\u5e94\u5546\u4fe1\u606f\u53ef\u80fd\u4f1a\u663e\u793a\u5728\u5e73\u53f0\u9875\u9762\u4e0a\u3002",
                    "\u6211\u4eec\u4e0d\u4f1a\u51fa\u552e\u4e2a\u4eba\u6570\u636e\u3002\u53ea\u6709\u5728\u5e73\u53f0\u8fd0\u8425\u3001\u6cd5\u5f8b\u5408\u89c4\u6216\u5b89\u5168\u5ba1\u6838\u9700\u8981\u65f6\uff0c\u4fe1\u606f\u624d\u53ef\u80fd\u88ab\u5171\u4eab\u3002"
                ]
            },
            {
                "title": "\u6570\u636e\u4fdd\u7559\u4e0e\u5b89\u5168",
                "paragraphs": [
                    "\u6211\u4eec\u4ec5\u5728\u5e73\u53f0\u8fd0\u8425\u3001\u6cd5\u5f8b\u4e49\u52a1\u4ee5\u53ca\u5408\u7406\u5ba1\u8ba1\u6216\u5b89\u5168\u8981\u6c42\u6240\u9700\u671f\u95f4\u4fdd\u7559\u8d26\u6237\u4fe1\u606f\u3002",
                    "Sea Requests \u91c7\u53d6\u5408\u7406\u7684\u6280\u672f\u548c\u7ba1\u7406\u63aa\u65bd\uff0c\u4fdd\u62a4\u8d26\u6237\u6570\u636e\u514d\u53d7\u672a\u7ecf\u6388\u6743\u7684\u8bbf\u95ee\u6216\u6ee5\u7528\u3002"
                ]
            }
        ]
    },
    "termsOfService": {
        "eyebrow": "\u6cd5\u5f8b",
        "title": "\u6761\u6b3e\u4e0e\u6761\u4ef6",
        "intro": "\u8fd9\u4e9b\u6761\u6b3e\u89c4\u8303\u4e70\u5bb6\u548c\u4f9b\u5e94\u5546\u5982\u4f55\u4f7f\u7528 Sea Requests \u5e76\u901a\u8fc7\u5e02\u573a\u8fdb\u884c\u4e92\u52a8\u3002",
        "updated": "\u6700\u540e\u66f4\u65b0\uff1a2026 \u5e74 5 \u6708 13 \u65e5",
        "sections": [
            {
                "title": "\u5e73\u53f0\u4f7f\u7528",
                "paragraphs": [
                    "Sea Requests \u662f\u4e00\u4e2a\u6d77\u4e8b\u5e02\u573a\uff0c\u4e70\u5bb6\u548c\u4f9b\u5e94\u5546\u53ef\u4ee5\u521b\u5efa\u8d26\u6237\u3001\u53d1\u5e03\u8bf7\u6c42\u3001\u5217\u51fa\u670d\u52a1\u5e76\u901a\u8fc7\u5e73\u53f0\u6c9f\u901a\u3002",
                    "\u7528\u6237\u6709\u8d23\u4efb\u4fdd\u6301\u8d26\u6237\u4fe1\u606f\u51c6\u786e\uff0c\u5e76\u4ec5\u5c06\u5e73\u53f0\u7528\u4e8e\u5408\u6cd5\u5546\u4e1a\u6d3b\u52a8\u3002"
                ]
            },
            {
                "title": "\u8d26\u6237\u4e0e\u6279\u51c6",
                "paragraphs": [
                    "\u8d26\u6237\u521b\u5efa\u53ef\u80fd\u9700\u8981\u7535\u5b50\u90ae\u4ef6\u9a8c\u8bc1\u548c\u7ba1\u7406\u5458\u6279\u51c6\u540e\u624d\u80fd\u83b7\u5f97\u5b8c\u6574\u8bbf\u95ee\u6743\u9650\u3002",
                    "Sea Requests \u53ef\u4ee5\u6682\u505c\u3001\u62d2\u7edd\u6216\u79fb\u9664\u5305\u542b\u865a\u5047\u4fe1\u606f\u3001\u6ee5\u7528\u5e73\u53f0\u6216\u9020\u6210\u8fd0\u8425\u98ce\u9669\u7684\u8d26\u6237\u3002"
                ]
            },
            {
                "title": "\u5217\u8868\u4e0e\u8bf7\u6c42",
                "paragraphs": [
                    "\u4f9b\u5e94\u5546\u8d1f\u8d23\u5176\u516c\u53f8\u4fe1\u606f\u3001\u670d\u52a1\u63cf\u8ff0\u3001\u8986\u76d6\u8303\u56f4\u548c\u8054\u7cfb\u65b9\u5f0f\u7684\u51c6\u786e\u6027\u3002",
                    "\u4e70\u5bb6\u8d1f\u8d23\u63d0\u4ea4\u6e05\u6670\u3001\u51c6\u786e\u5e76\u4e0e\u771f\u5b9e\u8fd0\u8425\u6216\u91c7\u8d2d\u9700\u6c42\u76f8\u5173\u7684\u8bf7\u6c42\u3002"
                ]
            },
            {
                "title": "\u8d23\u4efb",
                "paragraphs": [
                    "Sea Requests \u63d0\u4f9b\u5e73\u53f0\u57fa\u7840\u8bbe\u65bd\uff0c\u4e0d\u6210\u4e3a\u7528\u6237\u4e4b\u95f4\u4ea4\u6613\u3001\u62a5\u4ef7\u6216\u670d\u52a1\u4ea4\u4ed8\u7684\u4e00\u65b9\u3002",
                    "\u5404\u65b9\u4ecd\u9700\u5bf9\u81ea\u5df1\u7684\u5546\u4e1a\u51b3\u7b56\u3001\u6280\u672f\u5ba1\u6838\u3001\u5408\u89c4\u68c0\u67e5\u548c\u5408\u540c\u627f\u8bfa\u8d1f\u8d23\u3002"
                ]
            }
        ]
    },
