const browserLocale = () => {
    if (typeof window === 'undefined') {
        return fallbackLocale;
    }

    const saved = window.localStorage.getItem(storageKey);

    return locales.some((locale) => locale.code === saved) ? saved : fallbackLocale;
};

const activeLocale = ref(browserLocale());

const getMessage = (locale, path) => path.split('.').reduce((value, key) => value?.[key], messages[locale]);

export const setLocale = (locale) => {
    const nextLocale = locales.some((item) => item.code === locale) ? locale : fallbackLocale;

    activeLocale.value = nextLocale;

    if (typeof window !== 'undefined') {
        window.localStorage.setItem(storageKey, nextLocale);
        document.documentElement.lang = nextLocale === 'zh' ? 'zh-CN' : 'en';
    }
};

export const useI18n = () => {
    const t = (path, fallback = '') => {
        const translated = getMessage(activeLocale.value, path);
        const fallbackText = getMessage(fallbackLocale, path);

        if (translated !== undefined && translated !== null) {
            return translated;
        }

        if (fallbackText !== undefined && fallbackText !== null) {
            return fallbackText;
        }

        return fallback === null ? null : (fallback || path);
    };

    const text = (path) => computed(() => t(path));
    const section = (path) => computed(() => getMessage(activeLocale.value, path) ?? getMessage(fallbackLocale, path) ?? {});

    return {
        locale: readonly(activeLocale),
        locales,
        setLocale,
        section,
        t,
        text,
    };
};

export const initializeLocale = () => setLocale(activeLocale.value);
